component_data_script:
rows = props.get("questions") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

questions = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|", 1)]
	if not parts or not parts[0]:
		continue
	questions.append({"q": parts[0], "a": parts[1] if len(parts) > 1 else ""})
for i in range(len(questions)):
	# the FAQ opens the first answer: a bound `open` always renders (open="" is still open),
	# so the first item is its own variant with the attribute and the rest carry none
	questions[i]["first"] = i == 0
	questions[i]["rest"] = i > 0
	# the editor canvas keeps both variants in a repeater, so each also says whether it shows
	questions[i]["first_show"] = "true" if i == 0 else "false"
	questions[i]["rest_show"] = "false" if i == 0 else "true"
component.questions = questions
